-- Khóa kỹ năng "Costing" (Coil Cost Academy): cần đăng ký và được admin duyệt mới xem được nội dung.
-- Chạy 1 lần trong Supabase → SQL Editor, sau platform.sql. Chạy lại được: nội dung bài sẽ được cập nhật.

-- 1. Cho phép loại khóa 'skill' (khóa kỹ năng, không phải từ vựng)
alter table public.tracks drop constraint if exists tracks_kind_check;
alter table public.tracks add constraint tracks_kind_check check (kind in ('specialty','cefr','skill'));

insert into public.tracks(slug,name,kind,description,audience,join_policy,words_per_level,cats,sort) values
 ('costing','Costing – Coil Cost Academy','skill',
  'Cách tính giá thành 1 tấn thép mạ, sơn: từ CRC, lớp mạ, sơn, chi phí chuyển đổi, hao hụt, thu hồi đến giá bán. 6 module, bài ngắn và câu hỏi thực hành.',
  'Kế toán giá thành, kinh doanh, kế hoạch, sản xuất','approval',30,'{}',3)
on conflict (slug) do update set kind='skill';  -- giữ nguyên tên/mô tả admin đã sửa

-- 2. Nội dung khóa kỹ năng: chỉ người đã được duyệt (hoặc admin) mới đọc được
create table if not exists public.course_modules (
  track_id uuid not null references public.tracks(id) on delete cascade,
  idx int not null,
  data jsonb not null,
  updated_at timestamptz default now(),
  primary key (track_id, idx)
);
alter table public.course_modules enable row level security;
drop policy if exists "cm read" on public.course_modules;
create policy "cm read" on public.course_modules for select using (public.is_enrolled(track_id) or public.is_admin());
drop policy if exists "cm admin" on public.course_modules;
create policy "cm admin" on public.course_modules for all using (public.is_admin()) with check (public.is_admin());

-- 3. Điểm cao nhất mỗi module của từng người (đồng bộ mọi thiết bị)
create table if not exists public.course_progress (
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  track_id uuid not null references public.tracks(id) on delete cascade,
  module text not null,
  best int not null default 0,
  updated_at timestamptz default now(),
  primary key (user_id, track_id, module)
);
alter table public.course_progress enable row level security;
drop policy if exists "cp own" on public.course_progress;
create policy "cp own" on public.course_progress for all using (user_id = auth.uid() or public.is_admin()) with check (user_id = auth.uid());

-- 4. Nội dung 6 module
delete from public.course_modules where track_id = (select id from public.tracks where slug='costing');
insert into public.course_modules(track_id, idx, data) values
((select id from public.tracks where slug='costing'),1,$cc${"id": "m1", "title": "The big picture", "mins": 12, "lessons": [{"h": "What we are costing", "b": "<p>The model answers one question: <b>what does one ton of finished, coated coil cost us?</b> Every figure in the model is in <b>VND per ton of finished goods (FG)</b>.</p>\n  <div class=\"flow\"><span>CRC</span><i>→</i><span>MCL</span><i>→</i><span>CPL</span><i>→</i><span>CSL</span><i>→</i><span>Pack</span><i>→</i><span>Customer</span></div>\n  <ul><li><b>CRC</b>: cold-rolled coil, the steel we buy.</li><li><b>MCL</b>: metal coating line, adds the zinc-aluminium coating.</li><li><b>CPL</b>: coil paint line, adds primer, topcoat and backer.</li><li><b>CSL</b>: combination slitting line, cuts the coil to the customer's width.</li></ul>"}, {"h": "Five production routes", "b": "<p>Each product follows one route. The model has a separate costing sheet for each.</p>\n  <div class=\"tbl\"><table><tr><th>Route</th><th>What happens</th><th>Typical product</th></tr>\n  <tr><td><b>MCL</b></td><td>Coated only, no paint</td><td>Bare / Zincalume</td></tr>\n  <tr><td><b>PMCL</b></td><td>Painted on the paint section of the MCL itself</td><td>Economy painted</td></tr>\n  <tr><td><b>CPL1</b></td><td>Coated on MCL, then painted on CPL1</td><td>Zacs painted</td></tr>\n  <tr><td><b>PMCL+CPL1</b></td><td>Primer on PMCL, finish on CPL1</td><td>SUMO range</td></tr>\n  <tr><td><b>CPL2</b></td><td>Coated on MCL, then painted on CPL2</td><td>Colorbond®</td></tr></table></div>\n  <p class=\"small muted\">The route comes from the product master (Coded Data → Production line). Change the product and the route, line speeds and paint system all follow.</p>"}, {"h": "Four cost building blocks", "b": "<ul><li><b>Raw materials</b>: CRC, zinc, aluminium, paint, chemicals (resin, Bonderite, Okemcote, Zeus).</li>\n  <li><b>Conversion</b>: running the lines: labour, electricity, gas, supplies, repair & maintenance, overhead, depreciation.</li>\n  <li><b>Yield</b>: losses along the route mean we must buy more than one ton to sell one ton. Scrap and non-prime are partly <i>recovered</i> by selling them.</li>\n  <li><b>Logistics</b>: packaging and freight.</li></ul>\n  <div class=\"formula\">Full cost / ton FG = Materials + Conversion\n                  + Yield loss − Recovery\n                  + Packaging + Freight</div>"}, {"h": "The one formula everything uses", "b": "<p>Coating and paint are applied <b>per square metre</b>, but we sell <b>per ton</b>. The bridge between them is the area of one ton of steel.</p>\n  <div class=\"formula\">m² per ton = 1000 ÷ (7.85 × thickness_mm × CRC factor)</div>\n  <ul><li><b>7.85</b> = density of steel (t/m³).</li><li><b>CRC factor</b> = 1 for S33 tolerance, 0.971 for S60 (S60 steel runs slightly thinner for the same nominal size).</li></ul>\n  <div class=\"ex\"><span class=\"lbl\">Example</span><p>0.32 mm, S33 → 1000 ÷ (7.85 × 0.32) = <b>398 m²/ton</b>.<br>0.48 mm, S33 → 1000 ÷ (7.85 × 0.48) = <b>265 m²/ton</b>.</p></div>\n  <div class=\"note\">Thinner steel = more m² per ton = more paint and zinc per ton. That is why a 0.30 mm coil costs much more to paint, per ton, than a 0.48 mm coil.</div>"}], "quiz": [{"t": "mcq", "q": "Every cost in the model is expressed as…", "o": ["VND per coil", "VND per m²", "VND per ton of finished goods", "USD per hour"], "a": 2, "e": "Everything is normalised to one ton of finished goods so products can be compared and priced per ton."}, {"t": "match", "q": "Match each line to what it does.", "l": ["MCL", "CPL", "CSL", "PMCL"], "r": ["Adds zinc-aluminium coating", "Paints primer, topcoat and backer", "Slits the coil to customer width", "Coats and paints on one line"], "e": "MCL coats, CPL paints, CSL slits. PMCL is the MCL with its own paint section."}, {"t": "order", "q": "Put the CPL2 product flow in order.", "items": ["CRC purchased", "Metal coating on MCL", "Painting on CPL2", "Slitting on CSL", "Packaging"], "e": "Steel is coated before it is painted; slitting and packing come last."}, {"t": "mcq", "q": "Why does a thinner coil cost more to paint per ton?", "o": ["Thin steel needs thicker paint", "One ton of thin steel has more square metres to paint", "Thin coils run faster on the line", "Paint suppliers charge more for thin steel"], "a": 1, "e": "m²/ton = 1000 ÷ (7.85 × thickness). Halve the thickness and you double the area per ton."}, {"t": "calc", "q": "How many m² are in one ton of 0.40 mm S33 steel? (round to whole m²)", "ans": 318.47, "tol": 1.5, "unit": "m²/ton", "e": "1000 ÷ (7.85 × 0.40) = 318 m²/ton."}, {"t": "mcq", "q": "Which product family runs on the CPL2 route?", "o": ["Bare / Zincalume", "Colorbond®", "SUMO", "Economy painted on PMCL"], "a": 1, "e": "Colorbond® products are coated on the MCL and painted on CPL2."}]}$cc$::jsonb),
((select id from public.tracks where slug='costing'),2,$cc${"id": "m2", "title": "Steel and metal coating", "mins": 15, "lessons": [{"h": "CRC: the biggest single cost", "b": "<p>CRC is usually <b>about half</b> of the full cost. Its price depends on thickness and width.</p>\n  <ul><li><b>Final CRC price</b>: a table of price per ton for each thickness × width, agreed with the supplier for the month.</li>\n  <li><b>Thickness bands</b>: if a size is not in the final table, the model uses the supplier's band price (for example 0.29 ≤ T &lt; 0.35) including extra charges and transport.</li></ul>\n  <div class=\"ex\"><span class=\"lbl\">Example (Oct-2026)</span><p>0.32 × 1200 mm → Final CRC price <b>16,194,200 VND/t</b>.</p></div>"}, {"h": "Zinc and aluminium coating", "b": "<p>The MCL coats both sides with a zinc-aluminium alloy. The <b>coating mass</b> (AM70, AM100, AM150…) is the grams per m² on both sides together.</p>\n  <div class=\"formula\">Coating kg / ton = coating mass (g/m²) × m²/ton ÷ 1000\nZinc kg  = coating kg × zinc share\nAl kg    = coating kg × aluminium share</div>\n  <p>Zinc and aluminium are priced from LME-linked purchase prices each month. A loss allowance (zinc 6%, aluminium 3.5%) is added for dross and losses.</p>\n  <div class=\"ex\"><span class=\"lbl\">Example</span><p>AM150 on 0.32 mm: 150 × 398 ÷ 1000 ≈ <b>60 kg of coating per ton</b>.</p></div>"}, {"h": "Yield: buying more than you sell", "b": "<p>Every line loses some material (edge trim, head and tail, defects). Each line has a <b>yield</b>:</p>\n  <ul><li><b>YM</b> = MCL yield, <b>YC</b> = CPL yield, <b>YS</b> = CSL yield.</li></ul>\n  <div class=\"formula\">Overall yield = YM × YC × YS   (route-dependent)\nCRC needed per ton FG = 1 ÷ overall yield ÷ (1 − CRC scrap %)</div>\n  <div class=\"ex\"><span class=\"lbl\">Example</span><p>YM 0.98, YC 0.99, YS 1.00 → overall 0.970. With 1.5% CRC scrap, one ton FG needs 1 ÷ 0.970 ÷ 0.985 ≈ <b>1.047 t of CRC</b>.</p></div>\n  <div class=\"note\">CPL2 products pass the paint line twice in the yield formula (YM × YC × YC × YS), so their CRC input per ton is a little higher.</div>"}, {"h": "Two ways to show yield", "b": "<p>The cost card shows the same total in two ways:</p>\n  <ul><li><b>With yield factors</b> (Sheet1 P–AD): each material already includes the extra input caused by yield. Easy to read, hard to analyse.</li>\n  <li><b>Yield separated</b> (Sheet1 AH–BI): materials at a perfect-yield quantity, and the yield loss shown on its own lines (Yield loss MCL / CPL / CSL). Better for improvement work: you can see what each line's losses cost.</li></ul>"}], "quiz": [{"t": "mcq", "q": "If a thickness × width is missing from the Final CRC price table, the model…", "o": ["Shows zero", "Uses the supplier's thickness-band price", "Uses last month's price", "Stops with an error"], "a": 1, "e": "It falls back to the band price (CRC Price sheet) for the selected supplier."}, {"t": "calc", "q": "AM100 coating on 0.40 mm steel. Coating kg per ton? (318 m²/ton)", "ans": 31.8, "tol": 0.6, "unit": "kg/ton", "e": "100 g/m² × 318 m² ÷ 1000 = 31.8 kg per ton."}, {"t": "match", "q": "Match the yield symbol to its line.", "l": ["YM", "YC", "YS"], "r": ["Metal coating line", "Coil paint line", "Slitting line"], "e": "M = MCL, C = CPL, S = CSL."}, {"t": "mcq", "q": "Overall yield is 0.95. Ignoring CRC scrap, how much CRC is needed per ton of FG?", "o": ["0.95 t", "1.00 t", "1.053 t", "1.95 t"], "a": 2, "e": "1 ÷ 0.95 = 1.053 t."}, {"t": "mcq", "q": "Which view is better for finding where losses cost the most?", "o": ["With yield factors", "Yield separated", "Both are identical for analysis", "Neither shows yield"], "a": 1, "e": "The separated view puts each line's yield loss on its own line."}, {"t": "mcq", "q": "A thicker coil with the same coating mass needs…", "o": ["More zinc per ton", "Less zinc per ton", "The same zinc per ton", "No zinc"], "a": 1, "e": "Fewer m² per ton → fewer grams of coating per ton."}]}$cc$::jsonb),
((select id from public.tracks where slug='costing'),3,$cc${"id": "m3", "title": "Paint and chemicals", "mins": 15, "lessons": [{"h": "The paint system", "b": "<p>Each painted product has a <b>paint system</b> (ULT, XPD, PPS, APX…). It defines up to four layers:</p>\n  <ul><li><b>Top primer</b> and <b>topcoat</b> on the exposed side.</li><li><b>Bottom primer</b> and <b>backer</b> on the reverse side.</li></ul>\n  <p>The thickness of each layer is its <b>DFT</b>, dry film thickness in microns (µm), from Product Specification. Example: ULTRA = topcoat 22 µm, primer 8 µm, back primer 8 µm, backer 8 µm.</p>"}, {"h": "From DFT to litres per ton", "b": "<p>Paint is bought in litres of wet paint, but only the <b>solids</b> stay on the steel.</p>\n  <div class=\"formula\">Litres per m² = DFT (µm) ÷ (volume solid % ÷ 100) ÷ 1000\nLitres per ton = litres per m² × m²/ton × (1 + loss %)</div>\n  <div class=\"ex\"><span class=\"lbl\">Example</span><p>Topcoat 22 µm, volume solid 44.4% → 22 ÷ 0.444 ÷ 1000 = 0.0495 L/m².<br>× 398 m²/ton = <b>19.7 L/ton</b>, plus 3% paint loss ≈ 20.3 L/ton.</p></div>"}, {"h": "Paint price", "b": "<p>Each paint row in Paint System has a unit price in <b>VND per litre</b>. Each month the model takes the <b>highest</b> of three sources:</p>\n  <ul><li>Actual PO weighted-average cost (PO WAC)</li><li>PPG quotation</li><li>Akzo Nobel quotation</li></ul>\n  <p>If none of them has a price, the row shows <b>“Check latest price”</b> and every cost that uses that paint fails. In the web app this now shows as a clear warning.</p>\n  <div class=\"formula\">Paint cost / ton = Σ layers (litres per ton × VND per litre)</div>"}, {"h": "Chemicals", "b": "<ul><li><b>Resin</b>: clear or tinted coating on bare products (colour sets the price).</li>\n  <li><b>Bonderite / Okemcote</b>: pre-treatment before painting, based on chrome loading in mg/m² (both sides).</li>\n  <li><b>Zeus</b>: clean coat used on CPL2 products, about 2 µm wet film.</li></ul>\n  <p>Like paint, all are applied per m², so they scale with m²/ton.</p>"}], "quiz": [{"t": "match", "q": "Match each paint layer to the side it is on.", "l": ["Topcoat", "Backer", "Top primer", "Bottom primer"], "r": ["Exposed side, final colour", "Reverse side, final coat", "Exposed side, under the topcoat", "Reverse side, under the backer"], "e": "Primers sit under the finish coat on each side."}, {"t": "mcq", "q": "DFT means…", "o": ["Direct factory transfer", "Dry film thickness", "Daily feed tonnage", "Density factor of the topcoat"], "a": 1, "e": "Dry film thickness, in microns."}, {"t": "calc", "q": "Backer 8 µm, volume solid 40%. Litres per m²? (4 decimals)", "ans": 0.02, "tol": 0.0006, "unit": "L/m²", "e": "8 ÷ 0.40 ÷ 1000 = 0.0200 L/m²."}, {"t": "mcq", "q": "The paint unit price used each month is…", "o": ["The lowest of PO, PPG and Akzo", "The average of the three", "The highest of the three", "Always the PO price"], "a": 2, "e": "The model takes the maximum, which is the prudent choice."}, {"t": "mcq", "q": "A paint row shows “Check latest price”. What happens to products using it?", "o": ["Paint cost is zero", "Their cost columns fail until a price is entered", "They use last year's price", "Nothing"], "a": 1, "e": "Text in a price cell breaks the calculation; fix the price for the period."}, {"t": "mcq", "q": "Why do chemicals like Bonderite cost more per ton on thin steel?", "o": ["They are applied per m², and thin steel has more m² per ton", "Thin steel needs stronger chemicals", "They are priced per coil", "They don't; they are fixed per ton"], "a": 0, "e": "Everything applied per m² scales with m²/ton."}]}$cc$::jsonb),
((select id from public.tracks where slug='costing'),4,$cc${"id": "m4", "title": "Conversion cost", "mins": 15, "lessons": [{"h": "Machine rate", "b": "<p>Each line (MCL, PMCL, CPL1, CPL2, CSL) has a <b>machine rate</b>: what one hour of running costs, in VND/hour, split into:</p>\n  <div class=\"tbl\"><table><tr><th>Variable</th><th>Fixed</th></tr>\n  <tr><td>Variable labour<br>Electricity<br>Gas<br>Supplies<br>Repair & maintenance</td><td>Fixed labour<br>Manufacturing overhead<br>Depreciation</td></tr></table></div>\n  <p>Rates come from the budget (annual cost ÷ planned running hours).</p>"}, {"h": "Line speed to tons per hour", "b": "<p>The faster and wider the strip, the more tons per hour, and the cheaper each ton.</p>\n  <div class=\"formula\">Tons per hour = speed (m/min) × 60 × width (m)\n               × thickness (mm) × 7.85 ÷ 1000\n               × line speed achievement %</div>\n  <p>Speeds come from the Line speed tables: <b>MCL</b> by thickness × coating mass × grade, <b>PMCL</b> by thickness × coating, <b>CPL</b> by thickness × paint system.</p>\n  <div class=\"ex\"><span class=\"lbl\">Example</span><p>CPL at 60 m/min, 1.2 m wide, 0.32 mm: 60 × 60 × 1.2 × 0.32 × 7.85 ÷ 1000 = 10.9 t/h. At 80% achievement: <b>8.7 t/h</b>.</p></div>"}, {"h": "Conversion per ton", "b": "<div class=\"formula\">Conversion VND/ton = machine rate (VND/hour) ÷ tons per hour</div>\n  <div class=\"ex\"><span class=\"lbl\">Illustration</span><p>Full CPL2 rate ≈ 18.4 million VND/hour ÷ 8.7 t/h ≈ <b>2.1 million VND/ton</b>.</p></div>\n  <ul><li>The cost per ton goes <b>up</b> for thin, narrow or slow products: same hourly cost, fewer tons.</li><li>Each line on the route adds its own conversion: a CPL2 product pays MCL + CPL2 + CSL.</li></ul>"}, {"h": "Marginal versus full", "b": "<ul><li><b>Marginal (variable) conversion</b> uses only the variable part of the rate. It is what an extra ton really costs in cash.</li>\n  <li><b>Full conversion</b> adds fixed labour, overhead and depreciation, which are spread over planned volume.</li></ul>\n  <div class=\"note\">Use full cost for normal pricing. Use variable cost to judge a one-off order with spare capacity: any price above variable cost still contributes to fixed costs.</div>"}], "quiz": [{"t": "match", "q": "Sort these into variable or fixed conversion.", "l": ["Electricity", "Depreciation", "Gas", "Fixed labour"], "r": ["Variable", "Fixed", "Variable ", "Fixed "], "e": "Energy and supplies move with running hours; depreciation and fixed labour don't."}, {"t": "calc", "q": "Speed 50 m/min, width 1.0 m, 0.40 mm, 100% achievement. Tons per hour? (1 decimal)", "ans": 9.42, "tol": 0.1, "unit": "t/h", "e": "50 × 60 × 1.0 × 0.40 × 7.85 ÷ 1000 = 9.4 t/h."}, {"t": "mcq", "q": "Machine rate 12,000,000 VND/h, output 8 t/h. Conversion per ton?", "o": ["96,000,000", "1,500,000", "12,000,000", "667,000"], "a": 1, "e": "12,000,000 ÷ 8 = 1,500,000 VND/ton."}, {"t": "mcq", "q": "Which change lowers conversion cost per ton?", "o": ["Running the product narrower", "Running it slower", "Running a thicker gauge at the same speed", "Adding a second paint pass"], "a": 2, "e": "Thicker steel at the same speed means more tons per hour."}, {"t": "mcq", "q": "For a one-off order on spare capacity, the floor price is…", "o": ["Full cost", "Variable cost", "CRC price", "Zero"], "a": 1, "e": "Above variable cost the order still contributes to fixed cost, if capacity really is spare."}, {"t": "order", "q": "Order the steps to get conversion cost per ton.", "items": ["Look up line speed", "Convert speed to tons per hour", "Apply line speed achievement %", "Divide machine rate by tons per hour"], "e": "Speed → t/h → realistic t/h → VND per ton."}]}$cc$::jsonb),
((select id from public.tracks where slug='costing'),5,$cc${"id": "m5", "title": "Scrap, recovery and logistics", "mins": 12, "lessons": [{"h": "What happens to the lost tons", "b": "<p>Yield losses are not thrown away. They are sold:</p>\n  <ul><li><b>Non-prime</b>: coil with minor defects, sold at a lower price (example 7,000,000 VND/t).</li>\n  <li><b>Scrap</b>: edge trim and offcuts, sold as scrap (example 9,338,000 VND/t for CRC scrap).</li></ul>\n  <div class=\"formula\">Recovery credit = (1 − overall yield) × non-prime price\n               + scrap loss % × CRC input × scrap price</div>\n  <p>The credit is <b>negative</b> in the cost card because it reduces cost.</p>"}, {"h": "Coating content recovery", "b": "<p>Scrap that has already been coated or painted carries zinc, aluminium and paint. The model values that content separately on the \"Coating content recovery\" lines, so the recovery is not understated.</p>"}, {"h": "Slitting", "b": "<p>The customer's width is cut from a wider <b>mother coil</b> on the CSL. The <b>slitting width</b> table maps each finished width to the mother width it is cut from. The strip left over becomes slit scrap, a cost on the \"Slit scrap\" line.</p>\n  <div class=\"ex\"><span class=\"lbl\">Example</span><p>A 578 mm product is cut from a 1200 mm mother coil: two strips use 1156 mm, leaving 44 mm of scrap.</p></div>"}, {"h": "Packaging and freight", "b": "<ul><li><b>Packaging</b>: cost per ton by product group, from the Packaging Cost file (total packing cost ÷ tons per pack). If a product is missing from the file, the model falls back to 207,000 VND/t for CPL products.</li>\n  <li><b>Freight</b>: a cost per ton for delivery (example 940,000 VND/t), set per price period.</li></ul>\n  <div class=\"note\">Packaging names must match the product name exactly, accents included. “Bền Màu” and “BEN MAU” are different names to the model.</div>"}], "quiz": [{"t": "mcq", "q": "The recovery line in the cost card is negative because…", "o": ["It is an error", "Selling scrap and non-prime reduces cost", "It is a tax", "It is a currency difference"], "a": 1, "e": "Recovery is income from the lost tons, so it lowers the net cost."}, {"t": "match", "q": "Match the loss to how it is recovered.", "l": ["Minor surface defect coil", "Edge trim", "Leftover strip after slitting"], "r": ["Sold as non-prime", "Sold as CRC scrap", "Counted as slit scrap"], "e": "Defective coil → non-prime; trim → scrap; slitting offcut → slit scrap."}, {"t": "calc", "q": "Overall yield 0.97, non-prime price 7,000,000 VND/t. Non-prime credit per ton? (VND)", "ans": 210000, "tol": 500, "unit": "VND/ton", "e": "(1 − 0.97) × 7,000,000 = 210,000 VND per ton."}, {"t": "mcq", "q": "A product is missing from the Packaging Cost file. A CPL product then gets…", "o": ["Zero packaging", "The 207,000 VND/t fallback", "The most expensive pack", "An error"], "a": 1, "e": "The model's fallback is 9 × 23,000 = 207,000 VND/t for CPL routes."}, {"t": "mcq", "q": "Why can a correct-looking product name still miss its packaging cost?", "o": ["Packaging is only for exports", "Names must match exactly, including accents", "Packaging is per coil, not per ton", "The file is ignored"], "a": 1, "e": "“Bền Màu” vs “BEN MAU” do not match."}]}$cc$::jsonb),
((select id from public.tracks where slug='costing'),6,$cc${"id": "m6", "title": "From cost to price", "mins": 15, "lessons": [{"h": "Full cost and variable cost", "b": "<div class=\"tbl\"><table><tr><th>Line in the cost card</th><th>Variable</th><th>Full</th></tr>\n  <tr><td>CRC, zinc, Al, paint, chemicals</td><td>✓</td><td>✓</td></tr>\n  <tr><td>Variable conversion</td><td>✓</td><td>✓</td></tr>\n  <tr><td>Fixed conversion (fixed labour, overhead, depreciation)</td><td></td><td>✓</td></tr>\n  <tr><td>Yield loss less recovery</td><td>✓</td><td>✓</td></tr>\n  <tr><td>Packaging, freight</td><td>✓</td><td>✓</td></tr></table></div>\n  <p>Variable Product Cost (Sheet1 CG–CO) adds up the variable lines into <b>CO</b>.</p>"}, {"h": "Margin and selling price", "b": "<div class=\"formula\">Price at target margin = full cost ÷ (1 − margin %)\nContribution per ton    = price − variable cost\nContribution margin %   = contribution ÷ price</div>\n  <div class=\"ex\"><span class=\"lbl\">Example</span><p>Full cost 30,000,000, margin 10% → price 33,333,333.<br>Variable cost 26,000,000 → contribution 7,333,333 per ton (22%).</p></div>\n  <div class=\"note\">Margin on price is not markup on cost. 10% margin needs an 11.1% markup.</div>"}, {"h": "What moves the cost", "b": "<ul><li><b>Thickness</b>: drives m²/ton, so paint, coating and chemicals per ton, and tons per hour.</li>\n  <li><b>Width</b>: drives tons per hour, CRC price and slit scrap.</li>\n  <li><b>Coating mass</b>: zinc and aluminium per ton, and MCL speed.</li>\n  <li><b>Paint system and colour</b>: DFT, paint price and CPL speed.</li>\n  <li><b>Yields</b>: CRC input, yield loss and recovery.</li></ul>"}, {"h": "Governance: prices and master data", "b": "<p>In the new system two things are versioned and approved:</p>\n  <ul><li><b>Price period</b> (monthly): CRC, paint, zinc and aluminium, chemicals, packaging, freight.</li>\n  <li><b>Master data version</b> (when the process changes): products, specs, paint systems, line speeds, yields, machine rates.</li></ul>\n  <p>Each goes Draft → Submitted → Approved. Rejecting or reopening needs a reason, and the preparer cannot approve their own work. Because a period points to one master version, any past month can be recalculated exactly.</p>"}], "quiz": [{"t": "calc", "q": "Full cost 25,000,000 VND/t, target margin 20%. Selling price? (VND)", "ans": 31250000, "tol": 2000, "unit": "VND/ton", "e": "25,000,000 ÷ (1 − 0.20) = 31,250,000."}, {"t": "mcq", "q": "Price 31,250,000, variable cost 22,000,000. Contribution per ton?", "o": ["6,250,000", "9,250,000", "22,000,000", "31,250,000"], "a": 1, "e": "31,250,000 − 22,000,000 = 9,250,000."}, {"t": "match", "q": "Match each input change to what it mainly drives.", "l": ["Thinner gauge", "Wider coil", "Higher coating mass", "New paint colour"], "r": ["More m² per ton: more paint and zinc", "More tons per hour: lower conversion", "More zinc and aluminium per ton", "Different paint price and DFT"], "e": "Each input touches different blocks of the cost."}, {"t": "mcq", "q": "10% margin on price equals what markup on cost?", "o": ["10%", "9.1%", "11.1%", "20%"], "a": 2, "e": "1 ÷ 0.9 = 1.111 → 11.1% markup."}, {"t": "mcq", "q": "Who can approve a price period you prepared?", "o": ["You", "Any viewer", "An approver other than you (or admin)", "Nobody"], "a": 2, "e": "The preparer cannot approve their own period."}, {"t": "order", "q": "Order a monthly price update.", "items": ["Create the price period", "Upload CRC, paint and packaging files", "Submit for approval", "Approver approves and locks"], "e": "Draft → upload → submit → approve."}]}$cc$::jsonb);
